Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "datum.ROOM_TYPE == ''Entire home/apt'' ? ''Entire home'' : datum.ROOM_TYPE",
      "as": "room"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Total Listings",
          "as": "all"
        }
      ]
    },
    {
      "calculate": "datum[''Total Listings''] / datum.all",
      "as": "share"
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "r_all"
        }
      ],
      "sort": [
        {
          "field": "Total Listings",
          "order": "descending"
        }
      ]
    }
  ],
  "hconcat": [
    {
      "width": 190,
      "height": 130,
      "layer": [
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 0,
            "fontSize": 11,
            "color": "#8A7F6E",
            "text": "LISTINGS",
            "letterSpacing": 1.5
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "count",
                  "as": "n"
                }
              ]
            }
          ]
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 22,
            "fontSize": 34,
            "color": "#14617E",
            "fontWeight": 600
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "sum",
                  "field": "Total Listings",
                  "as": "t"
                }
              ]
            }
          ],
          "encoding": {
            "text": {
              "field": "t",
              "format": ","
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 76,
            "fontSize": 12,
            "color": "#B8860B",
            "fontWeight": 600
          },
          "transform": [
            {
              "window": [
                {
                  "op": "rank",
                  "as": "r"
                }
              ],
              "sort": [
                {
                  "field": "Total Listings",
                  "order": "descending"
                }
              ]
            },
            {
              "filter": "datum.r == 1"
            },
            {
              "calculate": "format(datum.share, ''.0%'') + '' '' + lower(datum.room)",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 96,
            "fontSize": 12,
            "color": "#6B6255"
          },
          "transform": [
            {
              "window": [
                {
                  "op": "rank",
                  "as": "r"
                }
              ],
              "sort": [
                {
                  "field": "Total Listings",
                  "order": "descending"
                }
              ]
            },
            {
              "filter": "datum.r == 2"
            },
            {
              "calculate": "format(datum.share, ''.0%'') + '' '' + lower(datum.room) + ''s''",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        }
      ]
    },
    {
      "width": 260,
      "height": 130,
      "encoding": {
        "y": {
          "field": "room",
          "type": "nominal",
          "title": null,
          "axis": {
            "domain": false,
            "ticks": false,
            "labelColor": "#6B6255",
            "labelFontSize": 11,
            "labelPadding": 6
          },
          "sort": "-x"
        },
        "x": {
          "field": "Total Listings",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "nice": false
          }
        }
      },
      "layer": [
        {
          "mark": {
            "type": "bar",
            "cornerRadiusEnd": 4,
            "height": {
              "band": 0.6
            }
          },
          "encoding": {
            "color": {
              "condition": {
                "test": "datum.r_all == 1",
                "value": "#F2B632"
              },
              "value": "#14617E"
            },
            "tooltip": [
              {
                "field": "room",
                "title": "Room type"
              },
              {
                "field": "Total Listings",
                "title": "Listings",
                "format": ","
              },
              {
                "field": "share",
                "title": "Share",
                "format": ".1%"
              }
            ]
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "dx": 4,
            "fontSize": 11,
            "color": "#6B6255"
          },
          "encoding": {
            "text": {
              "field": "Total Listings",
              "format": ","
            }
          }
        },
        {
          "transform": [
            {
              "joinaggregate": [
                {
                  "op": "max",
                  "field": "Total Listings",
                  "as": "mx"
                }
              ]
            },
            {
              "calculate": "datum.mx * 1.25",
              "as": "pad"
            }
          ],
          "mark": {
            "type": "point",
            "opacity": 0
          },
          "encoding": {
            "x": {
              "field": "pad",
              "type": "quantitative"
            }
          }
        }
      ]
    }
  ],
  "spacing": 16,
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI"
  }
}'
